SET "STOCK_COUNT" = #{orderCount},
"STOCK_PURCHASE" = #{orderPrice}
WHERE "USERNAME" = #{username}
AND
LPAD("ASSET_NO", 6, '0') = LPAD(#{stockCode}, 6, '0')

